import{c as o,Q as d,j as n,m as a}from"./chunks/framework.t4rEqR7d.js";const u=JSON.parse('{"title":"pagentv4 runtime 夯实计划","description":"","frontmatter":{},"headers":[],"relativePath":"pagentv4/hardening-plan.md","filePath":"pagentv4/hardening-plan.md"}'),t={name:"pagentv4/hardening-plan.md"};function r(c,e,s,p,l,i){return d(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="pagentv4-runtime-夯实计划" tabindex="-1">pagentv4 runtime 夯实计划 <a class="header-anchor" href="#pagentv4-runtime-夯实计划" aria-label="Permalink to &quot;pagentv4 runtime 夯实计划&quot;">​</a></h1><p><strong>范围</strong>:<code>src/pagentv4/runtime/</code> 与 <code>src/pagentv4/sandbox/</code>。 <strong>目标</strong>:巩固刚落地的 runner 继承链重构,消除遗留重复与约定漂移,不引入新功能。</p><p><strong>分级定义</strong>:</p><ul><li><strong>P0</strong>:已存在的重复或漂移,继续累积会加重维护成本,优先处理。</li><li><strong>P1</strong>:约定不一致或职责越界,本迭代内处理。</li><li><strong>P2</strong>:可读性/组织层面,择机处理,不影响功能。</li></ul><p><strong>验收总则</strong>:每项完成需满足 <code>ruff check</code> + <code>ruff format --check</code> 干净、<code>pytest tests/</code> 全绿、涉及英文文档改动时同步 <code>llms-full.txt</code>。</p><hr><h2 id="现状快照-已核实" tabindex="-1">现状快照(已核实) <a class="header-anchor" href="#现状快照-已核实" aria-label="Permalink to &quot;现状快照(已核实)&quot;">​</a></h2><p>重构后的继承链已收敛为单一循环骨架:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LoopAdapter                骨架:execute_tool / stream_agent_events / emit / emit_tool_events / run</span></span>
<span class="line"><span>  ├─ VanillaRunner         纯内存,after_* 用默认 no-op</span></span>
<span class="line"><span>  └─ BaseRunner            + thread / store / sandbox / skills,after_* 覆写为 flush</span></span>
<span class="line"><span>       ├─ ChatRunner       仅对话持久化(backend=&quot;none&quot;)</span></span>
<span class="line"><span>       ├─ CodeRunner       代码参数 / TOML 配置入口 + 懒初始化 sandbox</span></span>
<span class="line"><span>       └─ Runner           + inbound 控制面 + tool hooks</span></span></code></pre></div><ul><li>循环骨架已单份化,<code>run</code> 主体只在 <a href="./../../src/pagentv4/runtime/loop_adapter.py.html">loop_adapter.py</a> 写一次。</li><li>REPL 实际使用带 inbound + hooks 的 <code>Runner.create()</code>(见 <a href="./../../src/app/repl.py.html">repl.py</a>)。inbound / hooks 属于当前生产路径,但实现沿用重构前形态,尚未按新架构定型。</li><li>测试基线:<code>pytest tests/</code> 467 passed / 5 skipped。</li></ul><hr><h2 id="p0" tabindex="-1">P0 <a class="header-anchor" href="#p0" aria-label="Permalink to &quot;P0&quot;">​</a></h2><h3 id="p0-1-三处资源初始化逻辑重复-✅-已完成" tabindex="-1">P0-1 三处资源初始化逻辑重复 ✅ 已完成 <a class="header-anchor" href="#p0-1-三处资源初始化逻辑重复-✅-已完成" aria-label="Permalink to &quot;P0-1 三处资源初始化逻辑重复 ✅ 已完成&quot;">​</a></h3><p><strong>现状</strong> 「open sandbox → install skills → build system prompt → 组装 Agent」这一段在三处近乎逐字重复:</p><ul><li><a href="./../../src/pagentv4/runtime/code_runner.py.html"><code>open_code_resources</code></a>(code_runner.py L61-88)</li><li><a href="./../../src/pagentv4/runtime/base_runner.py.html"><code>BaseRunner.from_spec</code></a>(base_runner.py L100-157)</li><li><a href="./../../src/pagentv4/runtime/runner.py.html"><code>Runner.create</code></a>(runner.py L231-283)</li></ul><p>三份都在拼 <code>computer_desc</code> / <code>skills_prompt</code> / <code>system_tail</code>,并把 <code>sandbox.tools()</code> 与外部 tools 合并。改动一处需同步另外两处,已是漂移温床。</p><p><strong>目标</strong> 抽一个共享装配函数(输入 thread + skill_roots + tools + system 片段,输出 sandbox / skills / system_prompt / combined_tools),三处调用同一实现。</p><p><strong>验收</strong> 三处初始化路径不再各自拼接 system prompt;<code>test_pagentv4_base_runner</code> / <code>test_pagentv4_code_runner</code> / <code>test_pagentv4_sandbox</code> 全绿。</p><p><strong>落地</strong> 新增 <code>assemble_run_resources</code> + <code>RunResources</code>(base_runner.py),三处统一调用;删除 <code>open_code_resources</code>。<code>pytest tests/</code> 467 passed / 5 skipped,ruff 干净。</p><h3 id="p0-2-inbound-与-tool-hooks-按新架构定型" tabindex="-1">P0-2 inbound 与 tool hooks 按新架构定型 <a class="header-anchor" href="#p0-2-inbound-与-tool-hooks-按新架构定型" aria-label="Permalink to &quot;P0-2 inbound 与 tool hooks 按新架构定型&quot;">​</a></h3><p><strong>现状</strong><code>Runner</code> 已继承 <code>BaseRunner</code>,但 inbound 检查点(<code>emit</code> 内 <code>_apply_inbound_drain</code>)、<code>RunCancelled</code> 捕获(<code>_event_source</code>)、hooks 调度(<code>run_tool_with_hooks</code>)三段逻辑沿用重构前实现,作为后续重构的参考保留(见 runner.py L126-229)。checkpoint / drain 机制与 <code>emit</code> 骨架的边界尚未定型。</p><p><strong>目标</strong> 明确 inbound 与 hooks 作为「可叠加能力」挂进骨架的方式:界定 <code>emit</code> 检查点契约、<code>RunCancelled</code> 的传播路径、hooks 的前后置插入点,让 <code>Runner</code> 只覆写真差异点而不重写循环。保持公开 API(<code>runner.steer</code> / <code>cancel_run</code> / <code>permit_tool</code> / <code>deny_tool</code>、<code>Runner.create</code>)不变。</p><p><strong>验收</strong><code>test_pagentv4_runner_inbound</code> / <code>test_pagentv4_inbound</code> / <code>test_pagentv4_tool_hooks</code> 全绿;REPL(<code>app/repl.py</code>、<code>app/tool_permit.py</code>)行为不变。</p><hr><h2 id="p1" tabindex="-1">P1 <a class="header-anchor" href="#p1" aria-label="Permalink to &quot;P1&quot;">​</a></h2><h3 id="p1-1-coderunner-初始化时序统一-✅-已完成" tabindex="-1">P1-1 CodeRunner 初始化时序统一 ✅ 已完成 <a class="header-anchor" href="#p1-1-coderunner-初始化时序统一-✅-已完成" aria-label="Permalink to &quot;P1-1 CodeRunner 初始化时序统一 ✅ 已完成&quot;">​</a></h3><p><strong>现状</strong><code>CodeRunner</code> 有三种初始化路径,时序不一致:<code>__init__</code> 懒初始化(首次 run 前),<a href="./../../src/pagentv4/runtime/code_runner.py.html"><code>create</code></a>(L213-265)与 <a href="./../../src/pagentv4/runtime/code_runner.py.html"><code>from_toml</code></a>(L267-314)立即初始化。使用者需理解三者差异才能避免误用。</p><p><strong>目标</strong> 统一为单一构造入口 + 一个显式的初始化开关(懒 / 立即),<code>create</code> 与 <code>from_toml</code> 复用同一路径。</p><p><strong>验收</strong><code>test_pagentv4_code_runner</code> 中懒初始化与立即初始化两条用例均覆盖且全绿。</p><p><strong>落地</strong> 配置入口收敛到 <code>__init__</code>:<code>create</code> 改为 <code>cls(agent, **kwargs)</code> + <code>ensure_initialized</code> 的薄封装(不再复制 13 个参数声明);<code>from_toml</code> 解析出 spec 后直接复用 <code>create</code>,thread_id 兜底交给构造器。时序契约写进模块 docstring(懒 / 立即两条路径)。<code>pytest tests/</code> 467 passed / 5 skipped,ruff 干净。</p><h3 id="p1-2-thread-open-sandbox-与-backend-映射解耦-✅-已完成" tabindex="-1">P1-2 Thread.open_sandbox 与 backend 映射解耦 ✅ 已完成 <a class="header-anchor" href="#p1-2-thread-open-sandbox-与-backend-映射解耦-✅-已完成" aria-label="Permalink to &quot;P1-2 Thread.open_sandbox 与 backend 映射解耦 ✅ 已完成&quot;">​</a></h3><p><strong>现状</strong><a href="./../../src/pagentv4/ithread/local.py.html"><code>Thread.open_sandbox</code></a>(local.py L129-167)把 local / docker / podman / ssh 的配置映射逐分支写死在 Thread 内。新增 backend 需改 Thread。</p><p><strong>目标</strong> Thread 只负责准备 workdir 与 spec,后端选择与参数映射交给 sandbox 侧的工厂,Thread 不感知具体 backend 种类。</p><p><strong>验收</strong> 新增一个 backend 分支时无需改动 <code>ithread/local.py</code>;<code>test_pagentv4_thread</code> / <code>test_pagentv4_sandbox</code> 全绿。</p><p><strong>落地</strong> backend 映射知识下沉到 sandbox 层:新增 <code>open_sandbox_for_spec(profile, workdir, *, label=&quot;&quot;)</code> 工厂(<a href="./../../src/pagentv4/sandbox/sandbox.py.html">sandbox.py</a>),用 <code>SandboxProfile</code> Protocol 声明所需字段(ThreadSpec 结构上即满足),docker/podman 校验 image、ssh 校验 ssh_host 并解析 <code>~/.ssh/config</code> 都收敛于此。<code>Thread.open_sandbox</code> 简化为一次委托调用,不感知 backend 种类;新增 backend 只改工厂。<code>pytest tests/</code> 467 passed / 5 skipped,ruff 干净。</p><hr><h2 id="p2" tabindex="-1">P2 <a class="header-anchor" href="#p2" aria-label="Permalink to &quot;P2&quot;">​</a></h2><h3 id="p2-1-threadspec-字段分组-✅-已完成" tabindex="-1">P2-1 ThreadSpec 字段分组 ✅ 已完成 <a class="header-anchor" href="#p2-1-threadspec-字段分组-✅-已完成" aria-label="Permalink to &quot;P2-1 ThreadSpec 字段分组 ✅ 已完成&quot;">​</a></h3><p><strong>现状</strong><a href="./../../src/pagentv4/ithread/__init__.py.html"><code>ThreadSpec</code></a>(L38-149)把 conversation / sandbox / ssh / agent 四个关注点平铺在一个 dataclass 里,<code>from_dict</code> / <code>to_dict</code> 手工分段维护。字段增删时映射易漏。</p><p><strong>目标</strong> 按关注点拆成子配置(保持 <code>to_dict</code> / <code>from_dict</code> 的 TOML 兼容),或以更明确的分组表达四个 section。</p><p><strong>验收</strong><code>thread.toml</code> 读写往返不变;<code>test_pagentv4_ithread</code> 全绿。</p><p><strong>落地</strong> 字段保持扁平(消费方 <code>spec.backend</code> 等按属性读取不变),用 <code>toml_field(section, key, default)</code> 把每个字段的 <code>[section] key</code> 绑定进 dataclass metadata。<code>to_dict</code> / <code>from_dict</code> 改为从 <code>section_bindings()</code> 推导映射,新增字段只需声明一行,两个方向自动生效,不再有三处手工同步。<code>from_dict</code> 仍兼容旧的顶层扁平写法与未知键归入 <code>extra</code>。<code>pytest tests/</code> 467 passed / 5 skipped,ruff 干净。</p><h3 id="p2-2-backend-错误处理口径统一-✅-已完成" tabindex="-1">P2-2 backend 错误处理口径统一 ✅ 已完成 <a class="header-anchor" href="#p2-2-backend-错误处理口径统一-✅-已完成" aria-label="Permalink to &quot;P2-2 backend 错误处理口径统一 ✅ 已完成&quot;">​</a></h3><p><strong>现状</strong> 后端异常风格不一致:<code>LocalBackend</code> 命令失败返回 <code>CommandResult(ok=False)</code>,<code>SshBackend</code> 未启动直接 <code>raise RuntimeError</code>。上层对两类反馈的处理路径不同。</p><p><strong>目标</strong> 统一「命令级失败走 CommandResult、生命周期级错误走异常」的口径,并在文档中写明这条边界。</p><p><strong>验收</strong><code>test_pagentv4_sandbox</code> / <code>test_pagentv4_ssh</code> 全绿;<code>docs/pagentv4/sandbox.md</code> 补充口径说明。</p><p><strong>落地</strong> 在 <a href="./../../src/pagentv4/sandbox/base.py.html">base.py</a> 新增 <code>SandboxError</code> 基类与 <code>SandboxNotStartedError</code>,并把 <code>SandboxDeadError</code> 归到 <code>SandboxError</code> 之下,上层可用 <code>except SandboxError</code> 兜住整类「sandbox 不可用」。四类边界写进 <code>Backend</code> Protocol docstring:命令级失败走 <code>CommandResult(ok=False)</code>;未启动走 <code>SandboxNotStartedError</code>、start 失败走 <code>SandboxError</code>;配置不合法走 <code>ValueError</code>;文件语义级失败沿用 <code>FileNotFoundError</code> / <code>IsADirectoryError</code>。container / ssh backend 的「not started」与 start 环境失败改抛对应类型。新增三条契约测试,<code>docs/pagentv4/sandbox.md</code> 补错误处理表。<code>pytest tests/</code> 470 passed / 5 skipped,ruff 干净。</p><hr><h2 id="进度小结" tabindex="-1">进度小结 <a class="header-anchor" href="#进度小结" aria-label="Permalink to &quot;进度小结&quot;">​</a></h2><p>P0-1 / P1-1 / P1-2 / P2-1 / P2-2 均已完成。仅剩 P0-2(inbound / hooks 按新架构定型),按用户要求延后,单独一个迭代处理。</p><hr><h2 id="执行顺序建议" tabindex="-1">执行顺序建议 <a class="header-anchor" href="#执行顺序建议" aria-label="Permalink to &quot;执行顺序建议&quot;">​</a></h2><ol><li><strong>P0-1</strong>(共享装配函数):收益最直接,先做能减少后续各项的改动面。</li><li><strong>P1-1 / P1-2</strong>:依赖 P0-1 的统一装配,顺势收拢初始化时序与 backend 解耦。</li><li><strong>P0-2</strong>(inbound / hooks 定型):独立且影响 REPL,单独一个迭代,配合回归测试。</li><li><strong>P2-1 / P2-2</strong>:组织与口径层面,择机随手清理。</li></ol>`,53)])])}const _=o(t,[["render",r]]);export{u as __pageData,_ as default};
